        address actualMetadata =
            _readExactAddress(adapter, IStreamCoreFinalityAdapter.collectionMetadata.selector);
        if (actualCore != expectedCore || actualMetadata != expectedMetadata) {
            revert FinalityAdapterBindingMismatch(

